package dev.gamersclt.batcaverna.nativeapp;
import java.net.URI;
import java.util.*;
public final class CoverPolicy {
 public static boolean publicUrl(String source){try{URI u=new URI(source);return "https".equals(u.getScheme())&&u.getUserInfo()==null&&(u.getPort()==-1||u.getPort()==443)&&Arrays.asList("cdn2.unrealengine.com","cdn1.epicgames.com","cdn2.epicgames.com","cdn2.steamgriddb.com","cdn.steamgriddb.com","shared.cloudflare.steamstatic.com","shared.fastly.steamstatic.com","cdn.cloudflare.steamstatic.com","cdn.akamai.steamstatic.com","cdn.fastly.steamstatic.com","steamcdn-a.akamaihd.net","avatars.steamstatic.com","avatars.akamai.steamstatic.com","media.rawg.io","image.tmdb.org","images.igdb.com","s4.anilist.co","media.retroachievements.org","retroachievements.org").contains(u.getHost().toLowerCase(Locale.ROOT));}catch(Exception e){return false;}}
 public static String[] candidates(String source,String appid){LinkedHashSet<String> out=new LinkedHashSet<>();if(source!=null&&!source.trim().isEmpty()&&!source.equals("null")){String clean=source.trim().replace(" ","%20");if(clean.startsWith("http://")&&publicUrl("https://"+clean.substring(7)))clean="https://"+clean.substring(7);out.add(clean);}if(appid!=null&&appid.matches("[1-9][0-9]{0,9}")){out.add("https://shared.cloudflare.steamstatic.com/store_item_assets/steam/apps/"+appid+"/library_600x900.jpg");out.add("https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/"+appid+"/library_600x900.jpg");out.add("https://cdn.cloudflare.steamstatic.com/steam/apps/"+appid+"/library_600x900.jpg");out.add("https://shared.cloudflare.steamstatic.com/store_item_assets/steam/apps/"+appid+"/header.jpg");out.add("https://cdn.fastly.steamstatic.com/steam/apps/"+appid+"/header.jpg");out.add("https://cdn.akamai.steamstatic.com/steam/apps/"+appid+"/header.jpg");}return out.toArray(new String[0]);}
}
